INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 1, 'theory', 'Квиз: рождение JavaScript');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 0, 'Почему язык получил название JavaScript?', '["Он создан на основе Java","Его написала компания Sun","Он компилируется в байт-код Java","Это маркетинговый ход: Netscape договорилась с Sun, а к Java язык отношения не имеет"]', 3, 'Первый прототип назывался Mocha, затем LiveScript; имя JavaScript появилось в декабре 1995 года из-за популярности Java.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 1, 'Откуда в JavaScript взялись функции как значения и замыкания?', '["Из Scheme","Из языка C","Из Java","Из Python"]', 0, 'Брендана Айка пригласили, чтобы встроить в браузер Scheme; функциональные идеи остались, а синтаксис сделали похожим на Java и C.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 2, 'Что такое ECMAScript?', '["Браузер от Microsoft","Библиотека для работы с DOM","Название стандарта, по которому реализуется язык; JavaScript — торговая марка и самая известная реализация","Расширение протокола HTTP"]', 2, 'Netscape передала язык организации Ecma International; в 1997 году вышел стандарт ECMA-262, развивает его комитет TC39.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 3, 'Что сделали Gmail и Google Maps в 2004–2005 годах?', '["Заменили JavaScript на Flash","Показали, что страница может запрашивать данные в фоне без перезагрузки — подход назвали Ajax","Ввели модули в язык","Создали стандарт JSON"]', 1, 'Объект XMLHttpRequest существовал с 1999 года, но настоящую славу ему принесли именно эти приложения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 1, 4, 'Что принёс выход Chrome с движком V8 в 2008 году?', '["Менеджер пакетов npm","Классы в языке","Отказ от стандарта ECMAScript","Компиляцию JavaScript в машинный код прямо во время работы и гонку производительности браузеров"]', 3, 'V8 превратил JavaScript из «языка для украшательств» в быстрый язык, на котором можно писать большие программы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 2, 'theory', 'Квиз: Node.js и io.js');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 0, 'Почему Райан Даль построил Node.js вокруг неблокирующего ввода-вывода?', '["Потому что JavaScript нельзя выполнять в потоках","Классические серверы тратили поток на каждое соединение, а потоки впустую ждали диск и сеть","Потому что в браузерах нет ввода-вывода","Чтобы не пользоваться движком V8"]', 1, 'Однопоточный цикл событий обслуживает тысячи медленных клиентов: операция запускается, регистрируется колбэк, управление возвращается циклу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 1, 'Что такое libuv?', '["Кроссплатформенная библиотека, которая ждёт события ОС (epoll, kqueue, IOCP) и реализует цикл событий","Менеджер пакетов Node.js","Движок JavaScript от Google","Стандарт модулей CommonJS"]', 0, 'Первоначально использовались libev и libeio; libuv появилась, чтобы поддерживать и Windows.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 2, 'Что послужило причиной форка io.js в декабре 2014 года?', '["Технический спор о том, как работает V8","Переход на язык Rust","Недовольство закрытым управлением (одна компания), редкими выпусками и устаревшим V8","Запрет использования npm"]', 2, 'Разработчики хотели открытое управление техническим комитетом, быстрые выпуски по semver и свежий V8 с новыми возможностями языка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 3, 'Чем закончилась история io.js?', '["io.js был закрыт без последствий","io.js вытеснил Node.js и сохранил своё имя","Node.js перешёл под управление Microsoft","Проекты объединились: в сентябре 2015 вышел Node.js 4.0 на кодовой базе io.js"]', 3, 'Версия прыгнула с 0.12 сразу на 4: версии 1–3 уже занял io.js. Открытое управление и регулярные выпуски стали основой Node.js.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 2, 4, 'Как называется формат модулей, которым Node.js пользуется с ранних версий (require и module.exports)?', '["ES-модули","CommonJS","AMD","UMD"]', 1, 'require подключает файл, а module.exports отдаёт наружу нужное; ES-модули (import/export) появились позже и поддерживаются в Node.js встроенно.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 3, 'theory', 'Квиз: ES5, ES6, Babel и инструменты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 0, 'Почему между ES3 и ES5 прошло десять лет?', '["Не было желающих развивать язык","Язык был юридически заблокирован","Раскол в комитете вокруг амбициозной ES4 и необходимость поддерживать старые браузеры","Все ждали выхода Node.js"]', 2, 'ES4 отменили в 2008 году, скромные идеи (ES3.1) стали ES5; новый синтаксис нельзя было использовать, пока IE6–IE8 были распространены.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 1, 'Что принесла пятая редакция ES5 (2009)?', '["Строгий режим, объект JSON, методы массивов forEach/map/filter/reduce","Классы и модули","async/await","Стрелочные функции"]', 0, 'Классы, модули и стрелки появились только в ES2015, а async/await — в ES2017.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 2, 'Что делает Babel?', '["Сжимает изображения","Разбирает код в дерево и преобразует новый синтаксис в старый, понятный нужным браузерам","Запускает JavaScript на сервере","Заменяет npm"]', 1, 'Plugins и presets описывают преобразования; недостающие встроенные объекты дополняют полифилы core-js, а целевые браузеры задаёт browserslist.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 3, 'Какие возможности препроцессоры Sass, Less и Stylus добавили в CSS?', '["Асинхронные запросы","Типы данных","Классы","Переменные, вложенные правила, миксины и импорт файлов"]', 3, 'Сегодня часть этих возможностей (переменные, вложенность) появилась и в самом CSS.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 3, 4, 'Что произошло в марте 2016 года с пакетом left-pad?', '["Автор удалил пакет из 11 строк из npm, и сборки по всему миру упали","Его включили в стандарт языка","Он стал частью webpack","Его заменили на Babel"]', 0, 'Инцидент показал хрупкость цепочек поставок: огромные деревья мелких зависимостей зависят друг от друга.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 4, 'theory', 'Квиз: первая программа, Node и значения');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 0, 'Что делает движок V8 с часто вызываемыми функциями?', '["Выполняет их только интерпретатором","Переводит их обратно в исходный текст","Компилирует на лету в машинный код процессора (JIT)","Сохраняет их в файл на диске"]', 2, 'Текст разбирается в дерево, затем в байт-код, а «горячие» функции компилируются прямо во время работы в машинный код.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 1, 'Что произойдёт при const user = { n: 1 }; user.n = 2;?', '["Поле изменится: const запрещает только замену самой привязки","TypeError: присваивание константе","Объект будет скопирован","user станет неизменяемым"]', 0, 'const фиксирует привязку имени к значению, а не содержимое объекта: user = {} вызовет ошибку, а user.n = 2 — нет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 2, 'Чему равно typeof null?', '["\"null\"","\"undefined\"","\"number\"","\"object\""]', 3, 'Это историческая ошибка языка, которую не исправляют ради совместимости; проверять null нужно сравнением x === null.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 3, 'Почему 0.1 + 0.2 === 0.3 даёт false?', '["Из-за ошибки сложения в движке","Число одно — 64-битное дробное, и 0.1 с 0.2 в двоичном виде не точны","Потому что 0.3 — строка","Потому что оператор === сравнивает типы строк"]', 1, 'Все числа — IEEE 754 двойной точности, как double в C; десятичные дроби вроде 0.1 в двоичной системе приближённые.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 4, 'Какое выражение вернёт 0?', '["0 || 5","'''' || 0 || 5","null ?? 5","0 ?? 5"]', 3, 'Оператор ?? выбирает правый операнд только для null и undefined, поэтому 0 остаётся; || заменяет любое ложное значение, включая 0.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 5, 'theory', 'Квиз: операторы, приведение типов и сравнение');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 0, 'Чему равно ''5'' + 1 и ''5'' - 1?', '["6 и 4","''51'' и 4","''51'' и ''4''","6 и 6"]', 1, 'Если есть строка, + склеивает; минус всегда числовой оператор и приводит строку к числу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 1, 'Чему равно -7 % 3?', '["2","1","-2","-1"]', 3, 'Остаток берёт знак делимого, как в C; в Python результат был бы 2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 2, 'Почему [''10'', ''9'', ''1''].sort() и [10, 9, 1].sort() дают порядок «1, 10, 9»?', '["sort по умолчанию сравнивает элементы как строки","Из-за ошибки движка","sort работает только со строками","sort сортирует по убыванию"]', 0, 'Без функции сравнения элементы приводятся к строкам и сравниваются по кодам; для чисел нужен (a, b) => a - b.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 3, 'Что вернёт 0 ?? 5, а что — 0 || 5?', '["5 и 5","0 и 0","0 и 5","5 и 0"]', 2, '?? заменяет только null и undefined, поэтому 0 сохраняется; || заменяет любое ложное значение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 5, 4, 'Что делает выражение 0 < x < 10 при x = 15?', '["Возвращает false, как проверка диапазона","Бросает исключение","Возвращает true: (0 < 15) → true, затем true < 10","Возвращает 15"]', 2, 'Цепочка сравнений не проверяет диапазон: сначала получается булево значение, которое приводится к числу. Пишите x > 0 && x < 10.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 6, 'theory', 'Квиз: функции, область видимости и замыкания');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 0, 'Что выведет код: for (var i = 0; i < 3; i++) fns.push(() => i); затем вызов всех функций из fns?', '["0, 1, 2","undefined три раза","Ошибку ReferenceError","3, 3, 3"]', 3, 'var объявляет одну переменную на всю функцию, и все стрелки видят её после цикла, когда i равна 3. С let получилось бы 0, 1, 2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 1, 'Чем отличается стрелочная функция от обычной?', '["У стрелки нет собственного this: она берёт его из окружения, где создана","Стрелка нельзя вызвать с аргументами","Стрелка всегда выполняется асинхронно","Стрелка поднимается вверх области, как объявление"]', 0, 'Стрелка не имеет своих this и arguments. Поэтому она удобна для колбэков внутри методов, но не годится как метод объекта.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 2, 'Что такое замыкание?', '["Функция, которая вызывает саму себя","Блок кода в фигурных скобках","Функция вместе с окружением, в котором она создана, — она помнит его переменные","Функция без параметров"]', 2, 'Внутренняя функция хранит ссылку на окружение, где была создана, поэтому переменные доживают до тех пор, пока жива сама функция.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 3, 'Что произойдёт при обращении к let x до строки let x = 5;?', '["Вернётся undefined","ReferenceError: переменная во «временной мёртвой зоне»","Вернётся 5","SyntaxError при загрузке файла"]', 1, 'Имя известно движку с начала блока, но до инициализации обращаться к нему нельзя. Для var вернулся бы undefined.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 4, 'Чему равен f(1, null) при function f(a, b = 5) { return [a, b]; }?', '["[1, null]","[1, 5]","[1, undefined]","TypeError"]', 0, 'Значение по умолчанию подставляется только для undefined; null остаётся как есть.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 7, 'theory', 'Квиз: объекты, массивы и коллекции');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 0, 'Что произойдёт с оригиналом при const b = { ...a }; b.inner.x = 5; если inner — вложенный объект?', '["Оригинал тоже изменится: вложенный объект общий для обеих копий","Ничего: копия полностью независима","Будет ошибка TypeError","Изменится только b.inner"]', 0, 'Оператор ... делает поверхностную копию: ссылка на inner копируется, а не сам объект. Для глубокой копии нужен structuredClone.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 1, 'Чему равно [10, 9, 1].sort()?', '["[1, 9, 10]","[10, 9, 1]","[1, 10, 9]","[9, 10, 1]"]', 2, 'Без функции сравнения элементы приводятся к строкам и сравниваются по кодам: «1» < «10» < «9». Для чисел нужен (a, b) => a - b.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 2, 'Когда Map лучше обычного объекта?', '["Когда ключи — только короткие строки","Когда данные нужно передать по сети как JSON","Никогда: объект всегда быстрее","Когда нужны произвольные ключи (числа, объекты), порядок вставки и нет лишних унаследованных полей"]', 3, 'Map принимает любые ключи, помнит порядок вставки и не имеет полей вроде constructor; но JSON.stringify для Map даёт {}.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 3, 'Как получить массив без повторов [1, 2, 3] из [1, 2, 2, 3, 1]?', '["arr.unique()","[...new Set(arr)]","arr.filter(Set)","Object.keys(arr)"]', 1, 'Set хранит уникальные значения, а оператор ... разворачивает его обратно в массив с сохранением порядка первого появления.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 4, 'Что произойдёт с функцией и undefined в поле при JSON.stringify({ f() {}, u: undefined, n: 1 })?', '["Они превратятся в null","Вызовется ошибка","Они будут пропущены: получится {\"n\":1}","Они превратятся в строки"]', 2, 'Функции, undefined и символы пропускаются в объектах (а в массивах становятся null); NaN и Infinity превращаются в null.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 8, 'theory', 'Квиз: классы, прототипы и итераторы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 0, 'Что делает движок, когда поле не найдено в самом объекте?', '["Сразу возвращает undefined","Бросает ReferenceError","Ищет его по цепочке прототипов вверх, пока не встретит null","Копирует поле из глобального объекта"]', 2, 'Каждый объект ссылается на прототип; поиск идёт по цепочке до null, поэтому у любого объекта находится toString из Object.prototype.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 1, 'Что вернёт typeof для класса, объявленного через class Point {}?', '["''class''","''function''","''object''","''prototype''"]', 1, 'Класс — это функция-конструктор с синтаксическим сахаром; вызвать его без new нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 2, 'Что произойдёт при обращении к полю #balance вне класса (obj.#balance)?', '["Синтаксическая ошибка: приватное поле недоступно снаружи","Вернётся undefined","Вернётся значение поля","Поле будет создано заново"]', 0, 'Имена с решёткой — настоящая приватность: к ним нельзя обратиться снаружи, даже через квадратные скобки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 3, 'Когда в конструкторе дочернего класса нужно вызывать super()?', '["После всех обращений к this","Только если у родителя есть статические методы","Никогда: движок вызывает его сам","До первого обращения к this"]', 3, 'Объект создаёт родительский конструктор: до super() this ещё не существует, и обращение к нему даёт ReferenceError.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 8, 4, 'Какой метод должен быть у объекта, чтобы его можно было использовать в for…of?', '["forEach()","Метод с ключом Symbol.iterator, возвращающий итератор","next() на самом объекте","Свойство length"]', 1, 'Протокол итерации: [Symbol.iterator]() возвращает итератор с методом next(), дающим { value, done }. Генераторы пишут такие методы короче.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 9, 'theory', 'Квиз: модули и ошибки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 0, 'Что означает «живая привязка» у импорта в ES-модулях?', '["Модуль копирует значение при импорте","Импортёр видит изменения экспортируемой переменной, но сам менять её не может","Импорт можно перезаписать","Модуль выполняется при каждом импорте заново"]', 1, 'Привязка читается каждый раз заново: если модуль изменил экспортируемую переменную, все импортёры увидят новое значение; присвоить импортированному имени нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 1, 'Чем require в CommonJS принципиально отличается от import в ES-модулях?', '["require синхронный и может вызываться в любом месте кода","require работает только в браузере","require загружает код асинхронно","Между ними нет разницы"]', 0, 'require читает и выполняет файл синхронно, возвращая exports; import статический, поднимается наверх, а для условной загрузки есть import().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 2, 'Для чего нужен блок finally?', '["Он выполняется только при отсутствии ошибки","Он заменяет catch","Он выполняется всегда, в том числе при return и исключении, — там освобождают ресурсы","Он повторяет операцию"]', 2, 'finally срабатывает при любом выходе из try: нормальном, через return или через исключение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 3, 'Для чего служит поле cause у Error?', '["Хранит стек вызовов","Задаёт код возврата процесса","Ограничивает число повторов","Позволяет обернуть исходную ошибку в более осмысленную, не теряя первопричины"]', 3, 'new Error(''не удалось сохранить'', { cause: err }) сохраняет цепочку: в логе видно, что «вызвало» верхнюю ошибку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 9, 4, 'Какие операции можно безопасно повторять после сбоя?', '["Любые","Только идемпотентные: повтор которых не вредит, например чтение","Только записи в базу","Никакие"]', 1, 'Повтор списания денег удвоит платёж, а повтор чтения безопасен; число попыток ограничивают, паузу увеличивают экспоненциально с jitter.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 10, 'theory', 'Квиз: промисы и async/await');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 0, 'В каком порядке выведутся строки: setTimeout(log(''T''), 0); Promise.resolve().then(log(''P'')); log(''S'')?', '["T, P, S","S, P, T","S, T, P","P, S, T"]', 1, 'Сначала синхронный код (S), затем микрозадачи — обработчики промисов (P), и только потом таймеры (T).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 1, 'Чем Promise.allSettled отличается от Promise.all?', '["allSettled быстрее","allSettled запускает промисы по очереди","allSettled всегда дожидается всех и сообщает о каждом исходе, а all отклоняется при первой ошибке","Между ними нет разницы"]', 2, 'allSettled возвращает массив объектов { status, value | reason }, поэтому одна неудача не скрывает результатов остальных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 2, 'Почему await внутри items.forEach(async x => …) не дожидается завершения всех операций?', '["forEach не умеет ждать: он вызывает функции и сразу возвращается, а возвращённые промисы игнорирует","Потому что await работает только в циклах for","Потому что массив пуст","Из-за строгого режима"]', 0, 'Для последовательного ожидания используют for…of с await, а для параллельного — Promise.all(items.map(…)).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 3, 'Как правильно «отменить» запрос fetch?', '["Вызвать promise.cancel()","Присвоить промис в null","Использовать setTimeout","Передать в fetch signal от AbortController и вызвать abort()"]', 3, 'Промис сам не отменяется; fetch слушает сигнал и отклоняется с AbortError, свои операции должны подписываться на событие abort.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 10, 4, 'Что вернёт async-функция, в которой выполнен return 42?', '["Число 42","Промис, выполненный значением 42","undefined","Объект Error"]', 1, 'async-функция всегда возвращает промис: значение становится результатом, а исключение — причиной отклонения.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 11, 'theory', 'Квиз: функциональное программирование');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 0, 'Какая из функций чистая?', '["x => x + Math.random()","(a, b) => a + b","arr => arr.sort()","() => Date.now()"]', 1, 'Чистая функция зависит только от аргументов и ничего не меняет: sort() меняет массив на месте, остальные читают скрытое состояние.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 1, 'Почему const не делает массив неизменяемым?', '["Потому что const действует только на числа","Потому что в массивах нет методов","const запрещён в модулях","const запрещает лишь замену привязки: содержимое массива можно менять через push и другие методы"]', 3, 'Для неизменяемости нужно создавать копии ([...a, x]) и пользоваться методами toSorted, with, map и filter, а Object.freeze помогает ловить случайные правки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 2, 'В чём разница между compose(f, g) и pipe(g, f)?', '["Никакой: оба применяют сначала g, затем f; отличается лишь порядок записи","Результат разный","compose асинхронный","pipe работает только с числами"]', 0, 'compose записывают справа налево, как в математике, pipe — слева направо, как читают текст.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 3, 'Для чего в рекурсии применяют батут (trampoline)?', '["Чтобы ускорить вычисления в два раза","Чтобы кэшировать результаты","Чтобы не наращивать стек вызовов: вместо рекурсивного вызова возвращается функция-шаг, а цикл вызывает её","Чтобы вызывать функции параллельно"]', 2, 'В большинстве движков нет оптимизации хвостовых вызовов, и глубокая рекурсия падает с RangeError; батут превращает её в цикл.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 11, 4, 'Что гарантирует закон функтора «map(x => x) ничего не меняет»?', '["map всегда возвращает число","map всегда мутирует исходный массив","map выполняется лениво","Преобразование внутри контейнера не меняет его структуру: тождественное отображение возвращает эквивалентный контейнер"]', 3, 'Вместе со вторым законом (map композиции равен композиции map) это позволяет безопасно рефакторить цепочки map.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 12, 'theory', 'Квиз: библиотеки и приёмы ФП');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 0, 'Как работает Immer?', '["Копирует весь объект при каждом вызове","Замораживает объект и запрещает изменения","Даёт прокси-черновик: вы меняете его, а библиотека строит новое состояние, копируя только затронутые узлы","Хранит данные в базе"]', 2, 'produce(state, draft => …) записывает изменения черновика и возвращает новое неизменяемое значение; если изменений нет — возвращается исходная ссылка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 1, 'Что такое линза?', '["Пара геттера и сеттера, сфокусированная на части структуры; линзы можно композировать","Функция для увеличения интерфейса","Тип данных для чисел","Метод массива"]', 0, 'view читает часть, set заменяет её, over применяет функцию; линза на адрес и линза на город склеиваются в линзу на город в адресе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 2, 'В чём состоит идея трансдьюсеров?', '["Ускорить сеть","Преобразование применяется к редьюсеру, поэтому цепочку шагов можно выполнить за один проход без промежуточных массивов","Заменить промисы","Хранить данные в кэше"]', 1, 'mapT(f) принимает редьюсер и возвращает редьюсер, который применяет f перед накоплением; шаги склеиваются обычной композицией.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 3, 'Для чего в RxJS нужен switchMap?', '["Для переключения тем","Для объединения всех потоков параллельно","Для синхронного чтения","Для каждого значения запускает внутренний поток и отменяет предыдущий — например, устаревший поисковый запрос"]', 3, 'mergeMap запускает все внутренние потоки параллельно, concatMap — по очереди, а switchMap оставляет только последний.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 12, 4, 'Чем Validation отличается от Either?', '["Ничем","Validation работает только с числами","Validation накапливает все ошибки, а Either останавливается на первой","Validation — асинхронный"]', 2, 'Для проверки формы нужно показать пользователю все ошибки сразу, поэтому ошибки собираются в список.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 16, 'theory', 'Квиз: браузер изнутри');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 0, 'В каком порядке выполнится: setTimeout(A, 0); Promise.resolve().then(B); синхронный C?', '["A, B, C","C, A, B","C, B, A","B, C, A"]', 2, 'Сначала синхронный код (C), затем очередь микрозадач (B), и лишь потом следующая задача — таймер (A).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 1, 'Какие свойства дешевле всего анимировать?', '["width и height","transform и opacity — часто хватает одной композиции","margin и padding","font-size"]', 1, 'width и margin вызывают раскладку и отрисовку, а transform и opacity обрабатываются на этапе композиции на GPU.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 2, 'Что произойдёт, если одна задача выполняется 300 мс?', '["Страница не отреагирует на клик и пропустит кадры, пока задача не закончится","Ничего: браузер многопоточный","Задача будет прервана","Таймер сработает раньше"]', 0, 'Задачи не прерываются; главный поток один, поэтому долгие задачи делят на куски (до 50 мс) и отдают управление циклу событий.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 3, 'Чем отличаются defer и async у <script>?', '["async всегда быстрее","defer блокирует разбор HTML","defer выполняется после разбора по порядку, async — как только скачался","Между ними нет разницы"]', 2, 'Обычный скрипт останавливает разбор, defer и async — нет; модули (type=module) ведут себя как defer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 16, 4, 'Зачем нужны Web Workers?', '["Чтобы обращаться к DOM из другого потока","Чтобы выполнять тяжёлые вычисления в отдельном потоке со своим циклом событий, не блокируя интерфейс","Чтобы ускорить сеть","Чтобы хранить cookie"]', 1, 'У воркера нет доступа к DOM; он общается с главным потоком сообщениями через postMessage, данные копируются структурным клонированием.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 17, 'theory', 'Квиз: дерево DOM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 0, 'Чем отличаются children и childNodes?', '["Ничем","children — только элементы, childNodes — все узлы, включая текст и комментарии","childNodes — только элементы","children включает атрибуты"]', 1, 'Пробелы между тегами — текстовые узлы, поэтому первый узел из childNodes часто оказывается текстом.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 1, 'Как безопасно вставить пользовательский ввод на страницу?', '["el.textContent = input","el.innerHTML = input","document.write(input)","eval(input)"]', 0, 'textContent вставляет обычный текст: угловые скобки не превращаются в теги, поэтому внедрить скрипт нельзя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 2, 'Что вернёт element.closest(''form'')?', '["Первого потомка-формы","Все формы документа","Следующего соседа","Ближайшего предка (включая сам элемент), подходящего под селектор, или null"]', 3, 'closest поднимается вверх по предкам; он основа делегирования событий.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 3, 'Почему <button disabled="false"> всё равно отключена?', '["Из-за ошибки браузера","Потому что false — строка «true»","Булевы атрибуты работают по наличию, а не по значению","Потому что disabled — свойство стиля"]', 2, 'Включить кнопку можно, установив свойство btn.disabled = false или удалив атрибут.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 4, 'Чем querySelectorAll отличается от getElementsByClassName?', '["querySelectorAll быстрее всегда","Результат querySelectorAll — статический снимок, а getElementsByClassName — живая коллекция","Оба живые","Оба возвращают один элемент"]', 1, 'Живая коллекция обновляется при изменении дерева, поэтому её лучше превратить в массив перед обходом.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 18, 'theory', 'Квиз: CSS для программиста');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 0, 'Какой селектор специфичнее?', '[".a .b .c (0,3,0)","ul li a (0,0,3)","a:hover (0,1,1)","#id (1,0,0)"]', 3, 'Специфичность сравнивается по разрядам: один идентификатор сильнее любого числа классов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 1, 'Что делает box-sizing: border-box?', '["Включает padding и border в заданную ширину и высоту","Добавляет рамку","Убирает отступы","Включает flexbox"]', 0, 'При border-box width: 200px с padding: 20px остаётся шириной 200 пикселей — расчёты проще.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 2, 'Чем отличается grid от flex?', '["Grid — только для картинок","Flex — устаревший","Grid раскладывает в двух измерениях, flex — вдоль одной оси","Различий нет"]', 2, 'Grid удобен для каркаса страницы, flex — для содержимого компонентов; они часто работают вместе.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 3, 'Почему z-index: 1000000 может не помочь?', '["Максимум — 100","Родитель создал собственный контекст наложения, и выбраться из него нельзя","z-index работает только у fixed","Нужно !important"]', 1, 'Контекст наложения создают позиционированные элементы с z-index, opacity < 1, transform и другие.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 4, 'Какие свойства дешевле всего анимировать?', '["width и height","margin","top и left","transform и opacity"]', 3, 'Они часто обходятся одной композицией на GPU и не вызывают раскладку.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 19, 'theory', 'Квиз: события');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 0, 'В каком порядке событие проходит по дереву?', '["Всплытие → цель → погружение","Погружение (capture) → цель → всплытие (bubble)","Только цель","Цель → погружение"]', 1, 'Обычные слушатели срабатывают на всплытии; capture: true подписывает на погружение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 1, 'Чем отличается event.target от event.currentTarget?', '["Ничем","target — всегда document","target — где событие возникло, currentTarget — чей обработчик выполняется сейчас","currentTarget — всегда window"]', 2, 'При делегировании target — вложенный элемент, а currentTarget — контейнер, на котором висит обработчик.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 2, 'Зачем в делегировании используют closest?', '["Чтобы подняться от вложенной цели (например, значка) до нужной кнопки","Чтобы удалить элемент","Чтобы остановить всплытие","Чтобы создать копию"]', 0, 'Событие приходит от самого глубокого элемента под курсором, поэтому нужного предка находят через e.target.closest(селектор).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 3, 'Что даёт passive: true у слушателя прокрутки или касания?', '["Запрещает всплытие","Удаляет обработчик после первого вызова","Делает обработчик асинхронным","Браузеру не нужно ждать обработчика, чтобы начать прокрутку, — но preventDefault вызвать нельзя"]', 3, 'Пассивные слушатели убирают задержку прокрутки на мобильных устройствах.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 4, 'Какое свойство лучше использовать для горячих клавиш независимо от раскладки?', '["key","code","keyCode","char"]', 1, 'code описывает физическую клавишу (KeyS), key зависит от раскладки, а keyCode устарел.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 20, 'theory', 'Квиз: формы и хранилища');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 0, 'Какие поля попадут в данные формы при отправке?', '["Все поля","Только видимые","Только с атрибутом name, не отключённые; из флажков — отмеченные","Только text"]', 2, 'Поля без имени и disabled в данные не попадают, а кнопка — только если нажата именно она.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 1, 'Почему нельзя полагаться только на клиентскую валидацию?', '["Запрос можно отправить в обход формы, поэтому сервер обязан проверять заново","Браузеры её не поддерживают","Она слишком медленная","Она запрещена"]', 0, 'Клиентская проверка — удобство для пользователя, а не защита.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 2, 'Какой атрибут куки скрывает её от JavaScript?', '["Secure","SameSite","Path","HttpOnly"]', 3, 'HttpOnly запрещает чтение через document.cookie — поэтому идентификатор сессии хранят именно так.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 3, 'В чём особенность localStorage?', '["Асинхронный и без ограничений","Синхронный, хранит строки, квота около 5 МБ, данные доступны любому скрипту страницы","Очищается при закрытии вкладки","Отправляется с каждым запросом"]', 1, 'Для больших объёмов и запросов применяют IndexedDB, а секреты в localStorage не хранят.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 4, 'Что делает history.pushState?', '["Перезагружает страницу","Удаляет историю","Добавляет запись в историю и меняет адрес без перезагрузки","Отправляет запрос на сервер"]', 2, 'Когда пользователь жмёт «назад», срабатывает событие popstate — на нём строят маршрутизаторы одностраничных приложений.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 21, 'theory', 'Квиз: сеть в браузере');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 0, 'Когда промис fetch отклоняется?', '["При любом коде ответа 4xx и 5xx","Только при сетевой ошибке — ответ 404 или 500 считается успешно полученным","Только при коде 500","Никогда"]', 1, 'Успешность ответа проверяют сами по res.ok или res.status.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 1, 'Что произойдёт, если вызвать res.json() дважды у одного ответа?', '["Вернётся тот же результат","Запрос повторится","Тело станет пустой строкой","Второй вызов бросит ошибку — тело читается один раз; копию делают через clone()"]', 3, 'Тело — поток, который можно прочитать однократно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 2, 'Как отменить запрос fetch?', '["Передать signal от AbortController и вызвать abort()","res.stop()","Закрыть вкладку","Вызвать clearTimeout"]', 0, 'Промис отклоняется ошибкой AbortError; для таймаута есть AbortSignal.timeout(мс).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 3, 'Зачем браузер отправляет preflight-запрос OPTIONS?', '["Чтобы проверить скорость сети","Чтобы загрузить кеш","Чтобы спросить сервер, разрешены ли метод и заголовки междоменного запроса, до отправки настоящего","Чтобы сжать тело"]', 2, 'Простые запросы идут сразу, а непростые (например, с JSON и своими заголовками) требуют предварительной проверки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 21, 4, 'Чем WebSocket отличается от Server-Sent Events?', '["WebSocket односторонний, SSE двусторонний","Они одинаковы","SSE работает только по UDP","WebSocket двусторонний и сам не переподключается, SSE односторонний (сервер → клиент) и переподключается автоматически"]', 3, 'SSE — обычный HTTP-поток текста с автоматическим Last-Event-ID; WebSocket — отдельный протокол после Upgrade.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 22, 'theory', 'Квиз: воркеры и PWA');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 22, 0, 'Что нельзя передать в postMessage воркеру?', '["Дату","Map и Set","Массив байтов","Функцию или DOM-элемент"]', 3, 'Структурное клонирование не умеет функции и элементы страницы; даты, коллекции и циклические ссылки поддерживаются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 22, 1, 'Что делает список transfer при postMessage?', '["Передаёт владение буфером: у отправителя он становится пустым","Копирует буфер быстрее","Сжимает данные","Шифрует сообщение"]', 0, 'Перенос не копирует память, а отдаёт буфер другому потоку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 22, 2, 'Почему новая версия Service Worker может оставаться в состоянии waiting?', '["Ошибка в коде","Нет интернета","Старая версия ещё управляет открытыми вкладками","Закончилась квота"]', 2, 'Пока вкладки управляются старой версией, новая ждёт; skipWaiting ускоряет переход, но может смешать версии.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 22, 3, 'Какая стратегия подходит для файлов с хешем в имени, которые никогда не меняются?', '["Network Only","Cache First","Network First","Всегда обновлять"]', 1, 'Если содержимое определяется именем, безопаснее и быстрее всегда брать из кеша.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 22, 4, 'Зачем при activate удаляют старые кеши?', '["Чтобы освободить место и не смешивать версии файлов","Чтобы обновить manifest","Чтобы включить HTTPS","Это делает браузер сам"]', 0, 'Имя кеша включает версию; без очистки устаревшие хранилища копятся на диске.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 23, 'theory', 'Квиз: производительность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 23, 0, 'По какому показателю оценивают основные веб-показатели?', '["По среднему","По лучшему замеру","По 75-му процентилю реальных пользователей","По одному лабораторному запуску"]', 2, 'Среднее скрывает медленных пользователей, а один запуск шумен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 23, 1, 'Какая задача считается долгой (long task)?', '["Длиннее 50 мс","Длиннее 5 мс","Длиннее 500 мс","Любая асинхронная"]', 0, 'Пока выполняется задача длиннее 50 мс, страница не реагирует на ввод.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 23, 2, 'Что вызывает «молотилку раскладки»?', '["Использование transform","Чередование записи стилей и чтения размеров в цикле","Ленивая загрузка","Атрибут defer"]', 1, 'Чтение размеров после записи заставляет браузер пересчитать раскладку немедленно; сначала читают всё, потом пишут.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 23, 3, 'Зачем нужна виртуализация длинного списка?', '["Чтобы сжать данные","Чтобы ускорить сеть","Чтобы убрать сортировку","Чтобы держать в документе только видимые строки"]', 3, 'Общую высоту имитируют пустым блоком, а по прокрутке вычисляют диапазон индексов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 23, 4, 'Что мешает странице попасть в bfcache?', '["Обработчик unload и Cache-Control: no-store","Заголовок immutable","Атрибут loading=lazy","Brotli"]', 0, 'Кеш переходов не сохраняет страницы, которые не могут безопасно «заморозиться».');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 24, 'theory', 'Квиз: Node.js изнутри');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 24, 0, 'Что выполняется раньше после текущего обратного вызова?', '["process.nextTick и затем микрозадачи промисов","setTimeout(…, 0)","setImmediate","Все одновременно"]', 0, 'Между обратными вызовами цикл опустошает очередь nextTick, затем микрозадачи; повторяет, пока обе пусты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 24, 1, 'Что из этого выполняется в пуле потоков libuv?', '["Сетевые сокеты","Исполнение JavaScript","Таймеры","Файловые операции, DNS lookup, zlib"]', 3, 'Сокеты используют механизмы ядра (epoll, kqueue); файлы, dns.lookup, zlib и часть crypto — пул, по умолчанию четыре потока.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 24, 2, 'Что делает поле exports в package.json?', '["Список файлов для публикации","Устанавливает зависимости","Задаёт публичные точки входа пакета по условиям; не перечисленное закрыто","Включает TypeScript"]', 2, 'Кроме точек входа, перечисленных в exports, остальные файлы пакета нельзя подключить снаружи.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 24, 3, 'Какой код выхода у процесса, завершённого сигналом SIGTERM (номер 15)?', '["0","143","15","255"]', 1, 'Принято считать 128 + номер сигнала: 128 + 15 = 143.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 24, 4, 'Как правильно завершать сервис по SIGTERM?', '["Сразу вызвать process.exit()","Игнорировать сигнал","Перезапустить процесс","Перестать принимать подключения, дождаться текущих запросов, закрыть ресурсы, выйти — в пределах таймаута"]', 3, 'Корректное завершение не обрывает запросы; повторный сигнал или таймаут — повод выйти принудительно.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 25, 'theory', 'Квиз: HTTP-сервер на Node.js');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 25, 0, 'Что вернёт сервер, если путь существует, но метод не поддерживается?', '["404 Not Found","405 Method Not Allowed с заголовком Allow","500 Internal Server Error","200 OK с пустым телом"]', 1, '405 говорит, что путь известен, но метод не подходит; в заголовке Allow перечисляют допустимые методы. 404 — путь неизвестен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 25, 1, 'Как правильно читать тело запроса в Node.js?', '["Через req.body — оно уже готово","Собирать чанки из потока (data/for await), затем склеить и разобрать","Только синхронным fs.readFileSync","Тело нельзя прочитать"]', 1, 'req — читаемый поток: данные приходят кусками. Собираем, ограничиваем размер и только потом парсим.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 25, 2, 'Для чего служит функция next в middleware?', '["Закрывает сервер","Передаёт управление следующему обработчику цепочки","Перезапускает запрос","Отправляет ответ клиенту"]', 1, 'Middleware либо завершает ответ, либо вызывает next(), передавая запрос дальше по цепочке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 25, 3, 'Как защититься от запроса GET /../../etc/passwd при отдаче статики?', '["Не защищаться: браузер не отправит такой путь","Склеить путь с корнем, нормализовать и проверить, что результат внутри корня","Запретить все пути с точкой","Использовать только POST"]', 1, 'Нормализация (path.resolve) + проверка префикса корня исключают выход за пределы каталога.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 25, 4, 'Зачем тест запускает сервер на порту 0?', '["Это порт по умолчанию для HTTP","ОС выберет свободный порт — тесты не конфликтуют между собой","Порт 0 быстрее","Порт 0 отключает сеть"]', 1, 'Порт 0 просит систему выбрать свободный порт; его узнают у server.address() и подставляют в запросы.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 26, 'theory', 'Квиз: среды выполнения и тесты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 26, 0, 'Что означает «безопасность по умолчанию» в Deno?', '["Код шифруется при запуске","Программа не имеет доступа к файлам, сети и окружению, пока права не выданы флагами","Deno не запускает чужой код","Все права выданы, но логируются"]', 1, 'Без флагов --allow-* скрипт не может читать файлы, ходить в сеть и читать переменные окружения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 26, 1, 'Что объединяет Node, Deno и Bun и делает код переносимым?', '["Один и тот же движок","Набор веб-стандартов: fetch, Request/Response, URL, Web Streams, AbortController","Общий менеджер пакетов","Одинаковая файловая система"]', 1, 'Веб-стандартные API есть во всех средах. Платформенные возможности (файлы, процессы) лучше прятать за адаптером.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 26, 2, 'Как запустить встроенные тесты Node?', '["node --test","npm install mocha","node run tests","node --jest"]', 0, 'Модуль node:test и команда node --test не требуют сторонних библиотек.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 26, 3, 'Для чего нужны поддельные таймеры (fake timers)?', '["Чтобы ускорить процессор","Чтобы проверять код со временем (debounce, повторы, таймауты) без реального ожидания","Чтобы отключить setTimeout навсегда","Чтобы измерять память"]', 1, 'Тест продвигает время вручную (tick/advance), и все таймеры срабатывают мгновенно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 26, 4, 'Почему результат первого запуска бенчмарка нельзя считать показательным?', '["Первый запуск всегда быстрее","Движок ещё не оптимизировал код: нужен прогрев и повторы, а в отчёте — медиана","Первый запуск не считается","Таймер ещё не включён"]', 1, 'JIT-компиляция и кэши делают первые замеры медленнее. Нужны прогрев, много повторов и устойчивая статистика (медиана, разброс).');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 27, 'theory', 'Квиз: пакетные менеджеры и semver');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 27, 0, 'Какие версии разрешает диапазон ^1.2.3?', '["Только 1.2.3","Любые ≥ 1.2.3 и < 2.0.0","Любые ≥ 1.2.3 и < 1.3.0","Любые версии 1.x.x, включая 1.0.0"]', 1, 'Каретка допускает обновления, не меняющие самую левую ненулевую часть: ^1.2.3 = >=1.2.3 <2.0.0. ~1.2.3 = >=1.2.3 <1.3.0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 27, 1, 'Для чего нужен lock-файл?', '["Чтобы запретить публикацию пакета","Чтобы зафиксировать точные версии и хеши всех пакетов дерева — воспроизводимая установка","Чтобы ускорить запуск скриптов","Чтобы хранить пароли"]', 1, 'Диапазоны в манифесте дают разные версии в разное время; lock-файл записывает конкретные, и npm ci ставит строго по нему.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 27, 2, 'Что такое «фантомная зависимость»?', '["Пакет, который нельзя удалить","Код импортирует пакет, которого нет в манифесте, но он оказался рядом из-за подъёма в node_modules","Зависимость без версии","Зависимость от приватного реестра"]', 1, 'Из-за hoisting чужие зависимости видны проекту. Это ломается при обновлении; pnpm делает такие импорты невозможными.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 27, 3, 'Что означает 1.0.0-beta.2 по сравнению с 1.0.0?', '["Версия новее","Версия старше: предрелиз ниже релиза","Версия не сравнима","Это то же самое"]', 1, 'Согласно semver, предрелизная версия имеет более низкий приоритет, чем выпуск с теми же числами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 27, 4, 'В чём главное отличие хранения у pnpm?', '["Он не использует реестр","Файлы хранятся один раз в общем хранилище и подключаются жёсткими ссылками; node_modules строгий","Он хранит пакеты в облаке","Он не создаёт lock-файл"]', 1, 'Единое content-addressable хранилище экономит место и время, а структура node_modules открывает только объявленные зависимости.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 28, 'theory', 'Квиз: реестры и безопасность цепочки поставок');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 28, 0, 'Что означает dist-tag latest?', '["Самая новая версия по дате публикации","Метка, на какую версию указывает установка по умолчанию","Версия, помеченная как устаревшая","Предварительный выпуск"]', 1, 'Теги — подвижные метки в метаданных. npm install pkg берёт версию, на которую указывает latest; предрелизы публикуют с --tag next.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 28, 1, 'Что такое dependency confusion (подмена зависимости)?', '["Конфликт версий в дереве","Злоумышленник публикует в публичный реестр пакет с именем внутреннего пакета и большей версией","Опечатка в имени пакета","Дублирование в lock-файле"]', 1, 'Если менеджер смотрит в публичный реестр для внутреннего имени, он может выбрать «более свежий» вредный пакет. Защита: привязать scope к своему реестру и зарезервировать имена.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 28, 2, 'От чего защищает integrity (хеш архива) в lock-файле?', '["От вредного кода, опубликованного автором","От подмены архива: менеджер сверяет хеш после скачивания","От устаревших зависимостей","От конфликтов лицензий"]', 1, 'Хеш подтверждает, что архив тот же, что при составлении lock-файла. Он не гарантирует, что код безопасен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 28, 3, 'Что даёт provenance при публикации из CI?', '["Ускоряет установку","Подписанную запись: из какого репозитория, коммита и workflow собран пакет","Шифрует код пакета","Скрывает исходники"]', 1, 'Provenance (Sigstore) связывает пакет с конкретной сборкой, что позволяет проверить происхождение.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 28, 4, 'Что означает лицензия «MIT OR Apache-2.0»?', '["Нужно соблюдать обе лицензии","Пользователь выбирает любую из двух","Лицензия не определена","Использовать нельзя"]', 1, 'В SPDX-выражениях OR — выбор одной из лицензий, AND — обязательство соблюдать обе.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 29, 'theory', 'Квиз: сборщики');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 29, 0, 'Почему tree shaking хорошо работает с ES-модулями?', '["Они меньше по размеру","Импорты и экспорты статические: по ним известно, какие имена используются","Они всегда минифицированы","CommonJS запрещён в сборщиках"]', 1, 'Статическая структура import/export позволяет определить неиспользуемые экспорты без запуска кода. require() динамичен.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 29, 1, 'Что делает динамический import(''./editor.js'')?', '["Подключает модуль синхронно","Создаёт отдельный чанк и возвращает промис — модуль грузится по требованию","Удаляет модуль из бандла","Работает только в Node"]', 1, 'Сборщик выносит модуль и его зависимости в отдельный файл, который загружается при первом вызове.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 29, 2, 'Зачем в имя файла добавляют хеш содержимого (contenthash)?', '["Для защиты от копирования","Чтобы можно было кэшировать надолго: изменился код — изменилось имя","Чтобы файл был меньше","Для сортировки файлов"]', 1, 'Файл с хешем в имени не меняется — его кэшируют на год; новая версия получает новое имя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 29, 3, 'Для чего служит source map?', '["Для ускорения загрузки","Сопоставляет позиции в минифицированном коде с исходными: отладка видит ваши файлы и строки","Для сжатия картинок","Для карты сайта"]', 1, 'Source map — файл с VLQ-кодированными соответствиями «сгенерированная позиция → исходная». Его читают DevTools.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 29, 4, 'Что означает "sideEffects": false в package.json?', '["В пакете нет ошибок","Модули пакета не имеют побочных эффектов при загрузке: неиспользуемые можно безопасно удалять","Пакет нельзя публиковать","Запрещены импорты"]', 1, 'Сборщик смело отбрасывает импорты без использованных имён из таких пакетов; файлы с эффектами (например CSS) перечисляют массивом.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 30, 'theory', 'Квиз: TypeScript, ESLint и Prettier');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 30, 0, 'Что происходит с типами TypeScript при сборке?', '["Превращаются в проверки во время выполнения","Стираются: в выходном JavaScript их нет","Сохраняются в комментариях","Заменяются на any"]', 1, 'Типы существуют только на этапе проверки. Поэтому данные извне нужно проверять валидаторами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 30, 1, 'Как определяется совместимость типов в TypeScript?', '["По имени типа","Структурно: подходит значение с нужными полями нужных типов","По порядку полей","По месту объявления"]', 1, 'Структурная типизация: важна форма, а не название; лишние поля допустимы (кроме свежих литералов объектов).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 30, 2, 'Для чего нужен тип never при разборе union?', '["Для отключения проверок","После обработки всех вариантов остаётся never: компилятор подсветит необработанные новые варианты","Для приведения типов","Для асинхронных функций"]', 1, 'Проверка полноты (exhaustiveness): в ветке default значение имеет тип never; новый вариант union вызовет ошибку компиляции.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 30, 3, 'Чем занимается Prettier, а чем ESLint?', '["Prettier ищет баги, ESLint форматирует","Prettier приводит код к единому формату, ESLint ищет ошибки и плохие практики","Они делают одно и то же","Оба только проверяют типы"]', 1, 'Форматирование — Prettier; статический анализ по правилам — ESLint. Конфликтующие стилевые правила ESLint отключают (eslint-config-prettier).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 30, 4, 'Почему ответу сервера нельзя просто приписать тип через as?', '["as запрещён синтаксисом","as отключает проверку: компилятор не знает реальных данных — нужны unknown и валидация","as замедляет код","Типы не работают с JSON"]', 1, 'Тип не проверяется во время выполнения. На границе принимают unknown и проверяют type guard-ом или zod.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 31, 'theory', 'Квиз: реактивность и сигналы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 31, 0, 'Как сигнал узнаёт, что его прочитал эффект?', '["Эффект перечисляет сигналы вручную","Эффект перед запуском записывает себя в глобальную переменную «текущий наблюдатель», а сигнал при чтении смотрит туда","Сигнал сканирует исходный код","Через события DOM"]', 1, 'Автоматическое отслеживание: геттер сигнала добавляет текущий эффект в подписчики. После запуска переменная восстанавливается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 31, 1, 'Почему эффект пересобирает подписки при каждом запуске?', '["Чтобы замедлить работу","Набор прочитанных сигналов зависит от условий: подписка должна соответствовать реальному чтению","Это требование браузера","Чтобы очистить память браузера"]', 1, 'Ветвление меняет набор зависимостей. Старые подписки снимаются, новые собираются во время запуска.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 31, 2, 'Что такое глитч в реактивной системе?', '["Ошибка компиляции","Потребитель на миг видит несогласованное состояние: часть значений новая, часть старая","Утечка памяти","Бесконечный цикл"]', 1, 'В ромбовидной зависимости наивный пересчёт запускает потребителя до того, как обновились все промежуточные значения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 31, 3, 'Что делает batch(fn)?', '["Запускает fn в другом потоке","Откладывает запуск эффектов до конца fn: каждый нужный эффект выполняется один раз","Отменяет изменения","Удаляет эффекты"]', 1, 'Несколько записей сигналов внутри batch не вызывают промежуточных запусков; после выхода эффекты выполняются по одному разу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 31, 4, 'Почему items.push(x) не обновит интерфейс, если items хранится в обычном сигнале?', '["push запрещён в JS","Ссылка на массив не изменилась: сигнал сравнивает по Object.is; нужно записать новый массив","Сигналы не хранят массивы","push работает асинхронно"]', 1, 'Мутация на месте не меняет ссылку. Либо неизменяемые обновления (set([...items, x])), либо прокси-реактивность.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 32, 'theory', 'Квиз: виртуальный DOM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 32, 0, 'Что возвращает функция h(type, props, ...children)?', '["Настоящий DOM-элемент","Лёгкий объект-описание узла (vnode)","Строку HTML","Промис"]', 1, 'h создаёт обычный объект: тип, свойства, нормализованные дети. DOM строится позже функцией рендера.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 32, 1, 'Что делает алгоритм сравнения, если тип узла изменился (div → span)?', '["Обновляет свойства","Заменяет узел целиком вместе с поддеревом","Игнорирует изменение","Сравнивает детей по ключам"]', 1, 'При разных типах копаться внутри бессмысленно — узел создаётся заново.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 32, 2, 'Почему при вставке в начало списка без ключей обновляются все элементы?', '["Так устроен браузер","Сравнение идёт по индексу: каждый элемент сопоставляется с соседом","Из-за CSS","Это ошибка реакта"]', 1, 'По индексу первый новый сравнивается со старым первым и т. д.; с ключами элементы сопоставляются по идентичности.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 32, 3, 'Зачем нужна наибольшая возрастающая подпоследовательность (LIS) при сравнении списков?', '["Для сортировки значений","Чтобы определить максимальный набор элементов, остающихся на месте, и двигать минимум остальных","Для хеширования ключей","Для подсчёта высоты списка"]', 1, 'Элементы из LIS уже стоят в правильном относительном порядке — их не перемещают.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 32, 4, 'Чем подход Solid/Svelte отличается от виртуального DOM?', '["Они не используют JavaScript","Они обновляют конкретные узлы напрямую (компилятор или сигналы), без сравнения деревьев","Они всегда медленнее","Они не поддерживают компоненты"]', 1, 'Точечные обновления вместо повторного рендера и diff компонента: меньше работы, но другая модель и более сложный компилятор.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 33, 'theory', 'Квиз: компоненты и маршрутизатор');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 33, 0, 'Куда направлены потоки данных и событий в дереве компонентов?', '["Данные вверх, события вниз","Данные вниз через props, события вверх через обработчики","Всё через глобальные переменные","Только внутри одного компонента"]', 1, 'Однонаправленный поток: родитель передаёт props, ребёнок сообщает о событиях вызовом переданных функций.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 33, 1, 'Где следует держать состояние, нужное двум соседним компонентам?', '["В глобальной переменной","В ближайшем общем предке","В каждом из компонентов отдельно","В localStorage"]', 1, 'Состояние поднимают к ближайшему общему предку, а вниз передают значение и функции изменения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 33, 2, 'Для чего служит history.pushState?', '["Перезагружает страницу","Меняет адрес в строке браузера без перезагрузки и добавляет запись в историю","Очищает историю","Отправляет запрос на сервер"]', 1, 'pushState добавляет запись, replaceState заменяет текущую; на «назад»/«вперёд» приходит popstate.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 33, 3, 'Какие клики должен перехватывать компонент Link?', '["Все клики по любой ссылке","Обычный левый клик без модификаторов по ссылке на тот же origin без target=_blank","Только правые клики","Только клики с Ctrl"]', 1, 'Средний клик и клик с модификаторами нужны для «открыть в новой вкладке» — их оставляют браузеру.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 33, 4, 'Зачем нужна граница ошибок (error boundary)?', '["Для ускорения рендера","Чтобы исключение при отрисовке части интерфейса показывало запасной вид, а не роняло всё приложение","Чтобы скрывать ошибки сервера","Для проверки типов"]', 1, 'Граница ловит ошибки дочерних компонентов и показывает fallback с возможностью повторить.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 34, 'theory', 'Квиз: проект, тесты и деплой');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 34, 0, 'Почему dev-сервер Vite стартует почти мгновенно?', '["Он собирает весь проект заранее в один файл","Он отдаёт модули браузеру по запросу и преобразует их на лету","Он не обрабатывает TypeScript","Он работает только на одном файле"]', 1, 'Браузер сам грузит ES-модули, а Vite преобразует только запрошенные файлы; зависимости собираются один раз и кэшируются.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 34, 1, 'Зачем в имена собранных файлов добавляют хеш содержимого?', '["Чтобы файлы занимали меньше места","Чтобы неизменённые файлы брались из кэша, а изменённые загружались заново","Чтобы скрыть исходный код","Потому что так требует браузер"]', 1, 'Хеш меняется вместе с содержимым: можно кэшировать файл надолго и не бояться устаревшей версии.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 34, 2, 'Какие тесты в «пирамиде» должны быть самыми многочисленными?', '["Сквозные в браузере","Модульные: быстрые проверки функций и модулей","Ручные проверки","Все виды поровну"]', 1, 'Модульные тесты быстрые и стабильные, поэтому составляют основание пирамиды; сквозных делают мало и только для главных сценариев.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 34, 3, 'Что нужно настроить на хостинге для приложения с клиентской маршрутизацией?', '["Отключить кэш всех файлов","Для неизвестных путей отдавать главную страницу (index.html)","Запретить обновление страницы","Ничего не нужно"]', 1, 'Иначе при перезагрузке на адресе вроде /users/42 сервер вернёт 404: такого файла на диске нет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 34, 4, 'Зачем нужна непрерывная интеграция (CI)?', '["Чтобы заменить тесты","Чтобы на каждый коммит в чистом окружении запускались проверки, тесты и сборка","Чтобы ускорить браузер","Чтобы хранить исходный код"]', 1, 'CI делает проверки обязательными и независимыми от чьей-то машины: красный конвейер блокирует слияние.');
